package io.artio.api.inventory;

import org.springframework.boot.autoconfigure.condition.ConditionalOnWebApplication;import java.net.URI; import java.math.BigDecimal; import java.util.List; import java.util.UUID; import org.springframework.http.ResponseEntity; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@ConditionalOnWebApplication(type = ConditionalOnWebApplication.Type.SERVLET)
@RestController @RequestMapping("/api") public class InventoryController {
    private final InventoryApplicationService inventory; public InventoryController(InventoryApplicationService inventory){this.inventory=inventory;}
    @GetMapping("/warehouses") public List<InventoryApplicationService.WarehouseView> warehouses(){return inventory.warehouses();}
    @PostMapping("/warehouses") public ResponseEntity<InventoryApplicationService.WarehouseView> createWarehouse(@RequestBody InventoryApplicationService.WarehouseRequest request){var w=inventory.createWarehouse(request);return ResponseEntity.created(URI.create("/api/warehouses/"+w.id())).body(w);}
    @PutMapping("/warehouses/{id}/active") public InventoryApplicationService.WarehouseView warehouseActive(@PathVariable UUID id,@RequestBody ActiveRequest request){return inventory.setWarehouseActive(id,request.active());}
    @GetMapping("/warehouses/{id}/stock") public List<InventoryApplicationService.StockView> stockByWarehouse(@PathVariable UUID id){return inventory.stockByWarehouse(id);}
    @GetMapping("/stock/{sellableId}") public List<InventoryApplicationService.StockView> stockBySellable(@PathVariable UUID sellableId){return inventory.stockBySellable(sellableId);}
    @GetMapping("/inventory/low-stock") public List<InventoryApplicationService.LowStockView> lowStock(){return inventory.lowStock();}
    @GetMapping("/warehouses/{warehouseId}/stock-policies") public List<InventoryApplicationService.LowStockPolicyView> stockPolicies(@PathVariable UUID warehouseId){return inventory.lowStockPolicies(warehouseId);}
    @PutMapping("/warehouses/{warehouseId}/stock/{sellableId}/low-stock-policy") public InventoryApplicationService.LowStockPolicyView lowStockPolicy(@PathVariable UUID warehouseId,@PathVariable UUID sellableId,@RequestBody InventoryApplicationService.LowStockPolicyRequest request){if(request==null||request.threshold()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A low-stock threshold is required");return inventory.setLowStockPolicy(warehouseId,sellableId,request.threshold(),request.active());}
    @PostMapping("/warehouses/{warehouseId}/stock/{sellableId}/receipts") public InventoryApplicationService.StockView receive(@PathVariable UUID warehouseId,@PathVariable UUID sellableId,@RequestBody QuantityRequest request,JwtAuthenticationToken auth){if(request==null||request.quantity()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A receipt quantity is required");String reason=request.reason()==null||request.reason().isBlank()?"Stock receipt":boundedReason(request.reason());return inventory.receive(warehouseId,sellableId,request.quantity(),reason,actor(auth));}
    @PutMapping("/warehouses/{warehouseId}/stock/{sellableId}") public InventoryApplicationService.StockView adjust(@PathVariable UUID warehouseId,@PathVariable UUID sellableId,@RequestBody QuantityRequest request,JwtAuthenticationToken auth){if(request==null||request.quantity()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"An on-hand quantity and adjustment reason are required");return inventory.adjust(warehouseId,sellableId,request.quantity(),boundedReason(request.reason()),actor(auth));}
    @GetMapping("/warehouses/{warehouseId}/stock/{sellableId}/movements") public List<io.artio.inventory.StockMovement> movements(@PathVariable UUID warehouseId,@PathVariable UUID sellableId,@RequestParam(defaultValue="100") int limit){return inventory.movements(warehouseId,sellableId,limit);}
    @PostMapping("/inventory/reservations") public ResponseEntity<InventoryApplicationService.ReservationView> reserve(@RequestBody InventoryApplicationService.ReserveRequest request){var r=inventory.reserve(request);return ResponseEntity.created(URI.create("/api/inventory/reservations/"+r.id())).body(r);}
    @GetMapping("/orders/{orderId}/inventory-reservations") public List<InventoryApplicationService.ReservationView> byOrder(@PathVariable UUID orderId){return inventory.reservationsByOrder(orderId);}
    @PutMapping("/inventory/reservations/{id}/allocate") public InventoryApplicationService.ReservationView allocate(@PathVariable UUID id){return inventory.allocate(id);}
    @PutMapping("/inventory/reservations/{id}/release") public InventoryApplicationService.ReservationView release(@PathVariable UUID id){return inventory.release(id);}
    private static String boundedReason(String value){if(value==null||value.isBlank()||value.length()>500)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A reason between 1 and 500 characters is required");return value.trim();}
    private static UUID actor(JwtAuthenticationToken auth){return UUID.fromString(auth.getToken().getSubject());}
    public record QuantityRequest(BigDecimal quantity,String reason){public QuantityRequest(BigDecimal quantity){this(quantity,null);}} public record ActiveRequest(boolean active){}
}
